@pytest.mark.parametrize("auth_scenario", ["valid_auth", "invalid_auth", "missing_auth"])
def test_store_order_auth(api_client, auth_scenario, config_test_data):
    """
    Test authentication scenarios for store order retrieval.
    """
    orderId = config_test_data.get('orderId')
    endpoint = ENDPOINT.format(orderId=orderId)

    if auth_scenario == "invalid_auth":
        api_client.petstore_auth = "invalid_token"
    elif auth_scenario == "missing_auth":
        api_client.petstore_auth = None

    response = api_client.get(endpoint)

    if auth_scenario == "valid_auth":
        assert response.status_code == 200, "Expected 200 for valid auth"
    else:
        assert response.status_code == 401, f"Expected 401 for {auth_scenario}"

